+  return ['source_asset', 'source_image', 'source_ms_screenshot', 'official_ms_image']
+    .includes(first);
+}
+
+function restrictedSourceAsset(asset) {
+  if (!isRecord(asset)) return false;
+  if (asset.exists !== true) return asset.student_display_allowed === true;
+  return asset.review_status !== 'accepted' ||
+    asset.rights_status !== 'display_allowed' ||
+    asset.quality_status !== 'accepted';
+}
+
+function sourceAssetDisplayAllowed(asset) {
+  return isRecord(asset) &&
+    asset.exists === true &&
+    asset.review_status === 'accepted' &&
+    asset.rights_status === 'display_allowed' &&
+    asset.quality_status === 'accepted';
+}
+
+function structuredContentAvailable(payload) {
+  return payload?.structured_mark_point_posture?.status === 'accepted' ||
+    payload?.structured_mark_point_posture?.status === 'provisional';
+}
+
+function hasReleasedScoringAuthority(payload) {
+  return isRecord(payload?.scoring_authority_ref) &&
+    payload.scoring_authority_ref.status === 'released';
+}
+
+function validateDisplayGates({ schema, payload, fixtureId, errors }) {
+  if (!isRecord(payload.display_gates)) {
+    errors.push(errorWithFixture(fixtureId, 'display_gates_required'));
+    return;
+  }
+  if (Object.hasOwn(payload, 'student_display_allowed')) {
+    errors.push(errorWithFixture(fixtureId, 'coarse_student_display_allowed_forbidden'));
+  }
+  for (const field of DISPLAY_GATE_FIELDS) {
+    if (typeof payload.display_gates[field] !== 'boolean') {
+      errors.push(errorWithFixture(fixtureId, `display_gate_boolean_required:${field}`));
+    }
+  }
+  if (schema?.display_gate_contract?.answer_fact_posture_is_separate !== true) {
+    errors.push(errorWithFixture(fixtureId, 'answer_fact_posture_must_be_separate'));
+  }
+  const implications = schema?.display_gate_contract?.gate_implications ?? {};
+  if (
+    implications.payload_student_display_allowed_implies_official_ms_image_student_display_allowed !== false ||
+    implications.payload_student_display_allowed_implies_official_ms_text_student_display_allowed !== false
+  ) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'payload_student_display_does_not_imply_official_ms_display',
+    ));
+  }
+}
+
+function validateSourceAssetPosture({ payload, fixtureId, errors }) {
+  const asset = payload.source_asset;
+  if (!isRecord(asset)) {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_required'));
+    return;
+  }
+  if (typeof asset.exists !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_exists_boolean_required'));
+  }
+  if (!SOURCE_ASSET_REVIEW_STATUS.includes(asset.review_status)) {
+    errors.push(errorWithFixture(fixtureId, `invalid_source_asset_review_status:${asset.review_status}`));
+  }
+  if (!SOURCE_ASSET_RIGHTS_STATUS.includes(asset.rights_status)) {
+    errors.push(errorWithFixture(fixtureId, `invalid_source_asset_rights_status:${asset.rights_status}`));
+  }
+  if (!SOURCE_ASSET_QUALITY_STATUS.includes(asset.quality_status)) {
+    errors.push(errorWithFixture(fixtureId, `invalid_source_asset_quality_status:${asset.quality_status}`));
+  }
+  if (typeof asset.student_display_allowed !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_student_display_boolean_required'));
+  }
+  if (typeof asset.debug_display_allowed !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_debug_display_boolean_required'));
+  }
+  if (restrictedSourceAsset(asset)) {
+    if (
+      asset.student_display_allowed === true ||
+      payload.display_gates?.official_ms_image_student_display_allowed === true ||
+      payload.display_gates?.evidence_drawer_student_display_allowed === true
+    ) {
+      errors.push(errorWithFixture(
+        fixtureId,
+        'restricted_source_asset_student_display_not_allowed',
+      ));
+    }
+  }
+  if (asset.student_display_allowed === true && !sourceAssetDisplayAllowed(asset)) {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_student_display_requires_all_gates'));
+  }
+}
+
+function validateAcceptedScreenshotWithoutStructuredContent({ payload, fixtureId, errors }) {
+  const acceptedSource = sourceAssetDisplayAllowed(payload.source_asset);
+  if (!acceptedSource || structuredContentAvailable(payload)) return;
+  if (!['fallback_explanation', 'unavailable'].includes(payload.primary_display_mode)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'accepted_screenshot_without_structured_content_must_use_fallback_primary',
+    ));
+  }
+  if (payload.evidence_drawer_mode !== 'source_image_available') {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'accepted_screenshot_without_structured_content_evidence_drawer_required',
+    ));
+  }
+  if (payload.display_gates?.structured_feedback_student_display_allowed === true) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'accepted_screenshot_without_structured_content_must_not_claim_structured_feedback',
+    ));
+  }
+  if (
+    payload.scoring_posture === 'released_deterministic' ||
+    payload.point_judgement_allowed === true ||
+    payload.authoritative_score_allowed === true
+  ) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'accepted_screenshot_without_structured_content_must_not_claim_confident_scoring',
+    ));
+  }
+}
+
+function validateScoring({ payload, fixtureId, errors }) {
+  if (!SCORING_POSTURE.includes(payload.scoring_posture)) {
+    errors.push(errorWithFixture(fixtureId, `invalid_scoring_posture:${payload.scoring_posture}`));
+  }
+  if (typeof payload.point_judgement_allowed !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'point_judgement_allowed_boolean_required'));
+  }
+  if (typeof payload.authoritative_score_allowed !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'authoritative_score_allowed_boolean_required'));
+  }
+  const claimsAwardedMarks =
+    payload.scoring_posture === 'released_deterministic' ||
+    payload.point_judgement_allowed === true ||
+    payload.authoritative_score_allowed === true;
+  if (claimsAwardedMarks && !hasReleasedScoringAuthority(payload)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'scoring_authority_required_for_awarded_mark_claims',
+    ));
+  }
+  if (
+    payload.authoritative_score_allowed === true &&
+    payload.scoring_posture !== 'released_deterministic'
+  ) {
+    errors.push(errorWithFixture(fixtureId, 'authoritative_score_requires_released_posture'));
+  }
+  if (
+    payload.structured_mark_point_posture?.status === 'accepted' &&
+    !hasReleasedScoringAuthority(payload) &&
+    (payload.point_judgement_allowed === true || payload.authoritative_score_allowed === true)
+  ) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      'accepted_structured_marks_without_authority_must_not_claim_awarded_marks',
+    ));
+  }
+}
+
+function validateMissingMsNonBlocking({ payload, fixtureId, errors }) {
+  const missingMs =
+    payload.source_asset?.exists === false ||
+    payload.source_asset?.review_status === 'missing' ||
+    payload.review_availability?.status === 'unavailable';
+  if (!missingMs) return;
+  if (payload.row_presence?.included !== true) {
+    errors.push(errorWithFixture(fixtureId, 'missing_ms_must_not_drop_row'));
+  }
+  if (payload.non_blocking_attempt !== true) {
+    errors.push(errorWithFixture(fixtureId, 'missing_ms_must_be_non_blocking_attempt'));
+  }
+}
+
+export function validatePostAttemptReviewPayload({
+  schema,
+  payload,
+  boundary,
+  fixtureId = null,
+} = {}) {
+  const errors = [];
+  if (!isRecord(schema)) errors.push(errorWithFixture(fixtureId, 'schema_required'));
+  if (!isRecord(payload)) {
+    return {
+      status: 'fail',
+      errors: [errorWithFixture(fixtureId, 'payload_required')],
+    };
+  }
+
+  for (const field of arrayFrom(schema?.required_fields ?? REQUIRED_FIELDS)) {
+    if (!(field in payload)) {
+      errors.push(errorWithFixture(fixtureId, `required_field_missing:${field}`));
+    }
+  }
+
+  if (payload.schema_version !== schema?.payload_schema_version) {
+    errors.push(errorWithFixture(fixtureId, 'payload_schema_version_mismatch'));
+  }
+  if (payload.policy_version !== schema?.policy_version) {
+    errors.push(errorWithFixture(fixtureId, 'policy_version_mismatch'));
+  }
+  if (!isRecord(payload.generated_from_artifact_hashes)) {
+    errors.push(errorWithFixture(fixtureId, 'generated_from_artifact_hashes_required'));
+  }
+  if (payload.row_presence?.included !== true) {
+    errors.push(errorWithFixture(fixtureId, 'post_attempt_review_row_not_included'));
+  }
+  if (payload.question_identity?.subject_code !== SUBJECT_CODE) {
+    errors.push(errorWithFixture(fixtureId, 'invalid_subject_code'));
+  }
+  if (!isString(payload.question_identity?.question_id)) {
+    errors.push(errorWithFixture(fixtureId, 'question_id_required'));
+  }
+  if (!isString(payload.paper_session_key?.paper_code)) {
+    errors.push(errorWithFixture(fixtureId, 'paper_code_required'));
+  }
+  if (!REVIEW_AVAILABILITY_STATUS.includes(payload.review_availability?.status)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      `invalid_review_availability_status:${payload.review_availability?.status}`,
+    ));
+  }
+  if (payload.review_availability?.non_blocking_attempt !== true) {
+    errors.push(errorWithFixture(fixtureId, 'review_availability_must_be_non_blocking'));
+  }
+  if (!PRIMARY_DISPLAY_MODE.includes(payload.primary_display_mode)) {
+    if (primaryDisplayLooksSourceImage(payload.primary_display_mode)) {
+      errors.push(errorWithFixture(
+        fixtureId,
+        `forbidden_primary_display_mode:${payload.primary_display_mode}`,
+      ));
+    } else {
+      errors.push(errorWithFixture(
+        fixtureId,
+        `invalid_primary_display_mode:${payload.primary_display_mode}`,
+      ));
+    }
+  }
+  if (primaryDisplayLooksSourceImage(payload.primary_display_mode)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      `forbidden_primary_display_mode:${payload.primary_display_mode}`,
+    ));
+  }
+  if (sourceAssetFirst(payload)) {
+    errors.push(errorWithFixture(fixtureId, 'source_asset_first_display_not_allowed'));
+  }
+  if (!EVIDENCE_DRAWER_MODE.includes(payload.evidence_drawer_mode)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      `invalid_evidence_drawer_mode:${payload.evidence_drawer_mode}`,
+    ));
+  }
+  if (!isRecord(payload.answer_fact_posture)) {
+    errors.push(errorWithFixture(fixtureId, 'answer_fact_posture_required'));
+  } else if (typeof payload.answer_fact_posture.answer_fact_allowed !== 'boolean') {
+    errors.push(errorWithFixture(fixtureId, 'answer_fact_allowed_boolean_required'));
+  }
+  if (!CONTENT_POSTURE_STATUS.includes(payload.structured_mark_point_posture?.status)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      `invalid_structured_mark_point_status:${payload.structured_mark_point_posture?.status}`,
+    ));
+  }
+  if (!CONTENT_POSTURE_STATUS.includes(payload.worked_solution_posture?.status)) {
+    errors.push(errorWithFixture(
+      fixtureId,
+      `invalid_worked_solution_status:${payload.worked_solution_posture?.status}`,
+    ));
+  }
+
+  validateDisplayGates({ schema, payload, fixtureId, errors });
+  validateSourceAssetPosture({ payload, fixtureId, errors });
+  validateAcceptedScreenshotWithoutStructuredContent({ payload, fixtureId, errors });
+  validateScoring({ payload, fixtureId, errors });
+  validateMissingMsNonBlocking({ payload, fixtureId, errors });
+
+  if (payload.non_blocking_attempt !== true) {
+    errors.push(errorWithFixture(fixtureId, 'non_blocking_attempt_required'));
+  }
+  if (
+    boundary?.summary?.all_3530_question_rows_must_emit_post_attempt_review_payload !== true ||
+    boundary?.summary?.source_ms_screenshot_primary_display_allowed !== false
+  ) {
+    errors.push(errorWithFixture(fixtureId, 'upstream_post_attempt_boundary_not_confirmed'));
+  }
+
+  return {
+    status: errors.length === 0 ? 'pass' : 'fail',
+    errors: [...new Set(errors)],
+  };
+}
+
+function summarizeFixtures(fixtureResults) {
+  const fixtureCount = fixtureResults.length;
+  const fixturePassCount = fixtureResults.filter((fixture) => fixture.pass === true).length;
+  return {
+    fixture_count: fixtureCount,
+    fixture_pass_count: fixturePassCount,
+    fixture_fail_count: fixtureCount - fixturePassCount,
+  };
+}
+
+function fixturePayload(fixtures, fixtureId) {
+  return arrayFrom(fixtures?.fixture_results)
+    .find((fixture) => fixture?.fixture_id === fixtureId)?.payload;
+}
+
+function checkRestrictedSourceAssetsHidden(fixtures) {
+  return [
+    'candidate_screenshot_hidden',
+    'rights_unconfirmed_source_image_hidden',
+    'rights_blocked_source_image_hidden',
+    'quality_blocked_source_image_hidden',
+  ].every((fixtureId) => {
+    const payload = fixturePayload(fixtures, fixtureId);
+    return isRecord(payload) &&
+      restrictedSourceAsset(payload.source_asset) &&
+      payload.source_asset.student_display_allowed === false &&
+      payload.display_gates?.official_ms_image_student_display_allowed === false &&
+      payload.display_gates?.evidence_drawer_student_display_allowed === false;
+  });
+}
+
+function checkAcceptedScreenshotWithoutStructuredContent(fixtures) {
+  const payload = fixturePayload(fixtures, 'accepted_source_screenshot_missing_structured_marks');
+  return isRecord(payload) &&
+    sourceAssetDisplayAllowed(payload.source_asset) &&
+    payload.structured_mark_point_posture?.status === 'missing' &&
+    ['fallback_explanation', 'unavailable'].includes(payload.primary_display_mode) &&
+    payload.evidence_drawer_mode === 'source_image_available' &&
+    payload.display_gates?.structured_feedback_student_display_allowed === false &&
+    payload.scoring_posture !== 'released_deterministic' &&
+    payload.point_judgement_allowed === false &&
+    payload.authoritative_score_allowed === false;
+}
+
+function checkScoringPostureSeparated(fixtures) {
+  const noAuthority = fixturePayload(
+    fixtures,
+    'accepted_structured_marks_no_released_scoring_authority',
+  );
+  const released = fixturePayload(fixtures, 'structured_accepted');
+  return isRecord(noAuthority) &&
+    noAuthority.structured_mark_point_posture?.status === 'accepted' &&
+    noAuthority.scoring_authority_ref === null &&
+    noAuthority.scoring_posture === 'self_assessment_only' &&
+    noAuthority.point_judgement_allowed === false &&
+    noAuthority.authoritative_score_allowed === false &&
+    isRecord(released) &&
+    released.scoring_posture === 'released_deterministic' &&
+    hasReleasedScoringAuthority(released);
+}
+
+function checkMissingMsRowsPreserved(fixtures) {
+  const payload = fixturePayload(fixtures, 'ms_unavailable_fallback');
+  return isRecord(payload) &&
+    payload.row_presence?.included === true &&
+    payload.source_asset?.exists === false &&
+    payload.review_availability?.status === 'unavailable' &&
+    payload.non_blocking_attempt === true;
+}
+
+function failClosedValidatorResult(errors) {
+  const checks = VALIDATOR_CHECK_IDS.map((id) => ({ id, status: 'fail' }));
+  return {
+    schema_version: VALIDATOR_SCHEMA_VERSION,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    validator_status: 'fail',
+    summary: {
+      validation_status: 'fail',
+      fixture_count: 0,
+      fixture_pass_count: 0,
+      fixture_fail_count: 0,
+      check_count: checks.length,
+      check_pass_count: 0,
+      check_fail_count: checks.length,
+    },
+    checks,
+    errors,
+  };
+}
+
+export function validatePostAttemptReviewPayloadFixtures({
+  schema,
+  fixtures,
+  boundary,
+} = {}) {
+  if (!isRecord(schema)) return failClosedValidatorResult(['schema_required']);
+  if (!isRecord(fixtures) || !Array.isArray(fixtures.fixture_results)) {
+    return failClosedValidatorResult(['fixtures_required']);
+  }
+
+  const fixtureResults = fixtures.fixture_results.map((fixture) => {
+    const validation = validatePostAttemptReviewPayload({
+      schema,
+      payload: fixture?.payload,
+      boundary,
+      fixtureId: fixture?.fixture_id ?? 'unknown',
+    });
+    const expected = fixture?.expected_validation_status ?? 'pass';
+    return {
+      ...fixture,
+      actual_validation_status: validation.status,
+      pass: validation.status === expected,
+      errors: validation.errors,
+    };
+  });
+  const errors = fixtureResults.flatMap((fixture) => fixture.errors);
+  const summary = summarizeFixtures(fixtureResults);
+  const fixtureIds = fixtureResults.map((fixture) => fixture.fixture_id);
+  const checksById = {
+    accepted_screenshot_without_structured_content_degrades_review:
+      checkAcceptedScreenshotWithoutStructuredContent(fixtures),
+    all_required_fixture_states_present:
+      REQUIRED_FIXTURE_IDS.every((fixtureId) => fixtureIds.includes(fixtureId)),
+    fixture_payloads_validate:
+      summary.fixture_fail_count === 0,
+    forbidden_primary_display_modes_absent:
+      fixtureResults.every((fixture) => (
+        PRIMARY_DISPLAY_MODE.includes(fixture.payload?.primary_display_mode) &&
+        !primaryDisplayLooksSourceImage(fixture.payload?.primary_display_mode)
+      )),
+    granular_display_gates_enforced:
+      DISPLAY_GATE_FIELDS.every((field) => (
+        schema.display_gate_contract?.granular_fields?.includes(field) &&
+        fixtureResults.every((fixture) => (
+          typeof fixture.payload?.display_gates?.[field] === 'boolean' &&
+          !Object.hasOwn(fixture.payload ?? {}, 'student_display_allowed')
+        ))
+      )) &&
+      schema.display_gate_contract?.answer_fact_posture_is_separate === true,
+    missing_ms_rows_preserved:
+      checkMissingMsRowsPreserved(fixtures),
+    payload_display_does_not_imply_official_ms_display:
+      schema.display_gate_contract?.gate_implications
+        ?.payload_student_display_allowed_implies_official_ms_image_student_display_allowed === false &&
+      schema.display_gate_contract?.gate_implications
+        ?.payload_student_display_allowed_implies_official_ms_text_student_display_allowed === false,
+    primary_display_not_source_asset_first:
+      fixtureResults.every((fixture) => !sourceAssetFirst(fixture.payload)),
+    restricted_source_assets_hidden_from_students:
+      checkRestrictedSourceAssetsHidden(fixtures),
+    scoring_posture_separated_from_mark_points:
+      checkScoringPostureSeparated(fixtures),
+    upstream_boundary_loaded_and_passing:
+      boundary?.summary?.validation_status === 'pass' &&
+      boundary?.summary?.post_attempt_review_payload_required_rows === EXPECTED_ROW_COUNT &&
+      boundary?.summary?.all_3530_question_rows_must_emit_post_attempt_review_payload === true &&
+      boundary?.summary?.source_ms_screenshot_primary_display_allowed === false,
+  };
+  const checks = VALIDATOR_CHECK_IDS.map((id) => ({
+    id,
+    status: checksById[id] ? 'pass' : 'fail',
+  }));
+
+  if (!checksById.payload_display_does_not_imply_official_ms_display) {
+    errors.push('payload_student_display_does_not_imply_official_ms_display');
+  }
+  for (const check of checks) {
+    if (check.status !== 'pass') errors.push(`check_failed:${check.id}`);
+  }
+
+  const status = errors.length === 0 ? 'pass' : 'fail';
+  return {
+    schema_version: VALIDATOR_SCHEMA_VERSION,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    validator_status: status,
+    summary: {
+      validation_status: status,
+      ...summary,
+      check_count: checks.length,
+      check_pass_count: checks.filter((check) => check.status === 'pass').length,
+      check_fail_count: checks.filter((check) => check.status !== 'pass').length,
+    },
+    checks,
+    errors: [...new Set(errors)],
+  };
+}
+
+function buildReadback({ schema, fixtures, validatorResult }) {
+  return `# PostAttemptReviewPayload Schema Readback
+
+Issue: #${ISSUE}
+Parent: #${PARENT_ISSUE}
+Depends on: #${DEPENDS_ON_ISSUES.join(', #')}
+Validation status: \`${validatorResult.validator_status}\`
+
+## Schema
+
+- Payload schema version: \`${schema.payload_schema_version}\`
+- Policy version: \`${schema.policy_version}\`
+- Primary display modes: ${schema.enums.primary_display_mode.join(', ')}
+- Source image primary display allowed: false
+- Evidence drawer modes: ${schema.enums.evidence_drawer_mode.join(', ')}
+- Missing MS drops row: false
+- Fixture count: \`${fixtures.summary.fixture_count}\`
+
+## Display Gates
+
+- Payload display, structured feedback display, official MS text display, official MS image display, and evidence drawer display are separate gates.
+- Answer-fact posture is modeled separately from display gates.
+- Candidate, unreviewed, rights-unconfirmed, rights-blocked, and quality-blocked source screenshots are not student-display allowed.
+- Accepted and rights-approved source screenshots remain secondary evidence drawer content only.
+
+## Scoring
+
+- Scoring posture values: ${schema.enums.scoring_posture.join(', ')}
+- Accepted structured mark points do not imply released deterministic scoring authority.
+- Point judgement and authoritative score claims require an explicit released scoring_authority_ref.
+
+## Validator
+
+${validatorResult.checks.map((check) => `- ${check.id}: ${check.status}`).join('\n')}
+`;
+}
+
+export function buildPostAttemptReviewPayloadSchema(options = {}) {
+  const root = rootFromOptions(options);
+  const paths = pathsFromOptions(options);
+  const generatedAt = generatedAtFromOptions(options);
+  const inputs = options.inputs && typeof options.inputs === 'object'
+    ? options.inputs
+    : loadInputs(root, paths);
+  const schema = buildSchema({ root, paths, generatedAt });
+  const fixtures = buildFixtures({ schema, inputs });
+  const validatorResult = validatePostAttemptReviewPayloadFixtures({
+    schema,
+    fixtures,
+    boundary: inputs.boundary,
+  });
+  const readback = buildReadback({ schema, fixtures, validatorResult });
+  return {
+    schema,
+    fixtures,
+    validatorResult,
+    readback,
+    inputs,
+  };
+}
+
+export function writePostAttemptReviewPayloadArtifacts({ outRoot, artifacts }) {
+  const root = typeof outRoot === 'string' ? outRoot : repoRootFromScript();
+  const paths = pathsFromOptions({});
+  const outputPaths = artifacts.schema.output_artifacts ?? {};
+  writeJson(root, outputPaths.schema ?? paths.schemaOut, artifacts.schema);
+  writeJson(root, outputPaths.fixtures ?? paths.fixturesOut, artifacts.fixtures);
+  writeJson(root, outputPaths.validator ?? paths.validatorOut, artifacts.validatorResult);
+  writeText(root, outputPaths.readback ?? paths.readbackOut, artifacts.readback);
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  const artifacts = buildPostAttemptReviewPayloadSchema({ root: process.cwd() });
+  writePostAttemptReviewPayloadArtifacts({ outRoot: process.cwd(), artifacts });
+  console.log(JSON.stringify({
+    schema_version: 'post_attempt_review_payload_schema.cli_result.v1',
+    status: artifacts.validatorResult.validator_status,
+    output_artifacts: artifacts.schema.output_artifacts,
+    summary: artifacts.validatorResult.summary,
+  }, null, 2));
+}
